    counts = {}
    for row in grid:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)

    # Continue a diagonal pair only when its immediate next cell is on
    # the grid boundary.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w):
                    continue
                if grid[r2][c2] != color:
                    continue

                for rr, cc in ((r - dr, c - dc), (r2 + dr, c2 + dc)):
                    on_edge = rr in (0, h - 1) or cc in (0, w - 1)
                    if (0 <= rr < h and 0 <= cc < w and on_edge
                            and grid[rr][cc] == background):
                        out[rr][cc] = color

    return out
